import { EntitySchema } from "typeorm";
import { APP_SCHEMA } from "#core/db/schema";
import type { GroupEntity } from "#core/entities/group.entity";
import type { UserEntity } from "#core/entities/user.entity";

/** A note a member asked the bot to save in a group; long notes carry a summary for the agent's notes index. */
export interface NoteEntity {
  id: number;
  groupId: number;
  group?: GroupEntity;
  /** Null once the author is removed. */
  authorUserId: number | null;
  author?: UserEntity | null;
  content: string;
  summary: string | null;
  /** Generated by Postgres from content. */
  contentLength: number;
  createdAt: Date;
  updatedAt: Date;
}

export const NoteEntitySchema = new EntitySchema<NoteEntity>({
  name: "Note",
  tableName: "notes",
  schema: APP_SCHEMA,
  columns: {
    id: { type: "integer", primary: true, generated: "increment" },
    groupId: { type: "integer", name: "group_id" },
    authorUserId: { type: "integer", name: "author_user_id", nullable: true },
    content: { type: "text" },
    summary: { type: "text", nullable: true },
    contentLength: {
      type: "integer",
      name: "content_length",
      generatedType: "STORED",
      asExpression: "char_length(content)",
      insert: false,
      update: false,
    },
    createdAt: { type: "timestamptz", name: "created_at", createDate: true },
    updatedAt: { type: "timestamptz", name: "updated_at", updateDate: true },
  },
  relations: {
    group: {
      type: "many-to-one",
      target: "Group",
      onDelete: "CASCADE",
      joinColumn: { name: "group_id", foreignKeyConstraintName: "notes_group_id_fkey" },
    },
    author: {
      type: "many-to-one",
      target: "User",
      nullable: true,
      onDelete: "SET NULL",
      joinColumn: { name: "author_user_id", foreignKeyConstraintName: "notes_author_user_id_fkey" },
    },
  },
  checks: [
    { name: "notes_content_not_empty_check", expression: `content_length > 0` },
    { name: "notes_summary_length_check", expression: `summary IS NULL OR char_length(summary) <= 100` },
    { name: "notes_summary_required_check", expression: `content_length <= 100 OR summary IS NOT NULL` },
  ],
  indices: [
    { name: "notes_group_id_created_at_idx", columns: ["groupId", "createdAt"] },
    { name: "notes_author_user_id_idx", columns: ["authorUserId"] },
  ],
});
